-- Name: aocr_or_detalle_after_recalc(); Type: FUNCTION; Schema: public; Owner: root
--

CREATE FUNCTION public.aocr_or_detalle_after_recalc() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_orden_id INT;
BEGIN
    v_orden_id := COALESCE(NEW.orden_id, OLD.orden_id);
    PERFORM public.aocr_or_recalcular_orden(v_orden_id);
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.aocr_or_detalle_after_recalc() OWNER TO root;

--
-- Name: aocr_or_detalle_calcular_linea(); Type: FUNCTION; Schema: public; Owner: root
--

CREATE FUNCTION public.aocr_or_detalle_calcular_linea() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- subtotal = cantidad * valor_unitario
    NEW.subtotal := ROUND(COALESCE(NEW.cantidad,0) * COALESCE(NEW.valor_unitario,0), 2);

    -- admin = subtotal * porcentaje_admin
    NEW.admin := ROUND(COALESCE(NEW.subtotal,0) * COALESCE(NEW.porcentaje_admin,0), 2);

    -- total_linea = subtotal + admin
    NEW.total_linea := ROUND(COALESCE(NEW.subtotal,0) + COALESCE(NEW.admin,0), 2);

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.aocr_or_detalle_calcular_linea() OWNER TO root;

--
-- Name: aocr_or_recalcular_orden(integer); Type: FUNCTION; Schema: public; Owner: root
--

CREATE FUNCTION public.aocr_or_recalcular_orden(p_orden_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_sub NUMERIC(12,2);
    v_adm NUMERIC(12,2);
    v_tot NUMERIC(12,2);
BEGIN
    SELECT
        COALESCE(SUM(subtotal),0),
        COALESCE(SUM(admin),0),
        COALESCE(SUM(total_linea),0)
    INTO v_sub, v_adm, v_tot
    FROM public.aocr_or_orden_detalle
    WHERE orden_id = p_orden_id;

    UPDATE public.aocr_or_orden
    SET subtotal = v_sub,
        admin = v_adm,
        total = v_tot
    WHERE id = p_orden_id;
END;
$$;


ALTER FUNCTION public.aocr_or_recalcular_orden(p_orden_id integer) OWNER TO root;

